        rawContent: `The '''Alliance of Planets Space Police''' patrols the common shipping lanes within charted space, preventing piracy. It also enforces the trade regulations of the [[Alliance of Planets]], specifically the restrictions against the trading of power sources and weapons technology.

The Space Police is almost universally hated by the [[Council of Independent Nations]] members for its role in enforcing what they considered an illegal blockade of their worlds.

[[Category:Alliance of Planets]]`
