        rawContent: `The Rank system of the [[Mozihr Getah Tashir Fahr‎|Mozihr Getah]] is a simple one, with '''Wehrmon''' and '''Kihtan''' ranks.

==Wehrmon==

Wehrmon is any rating below that of a Kihtan officer. The term includes non-Kihtan officers. Though it is the lowest of the ranks, it is important. The Wehrmon are the core of ship crews and maintenance teams that keep the Lorithos war machines running.

*Seghra - The [[Lorithos]] rank of Seghra (W1) is held by all unintelligent robotic units, for the purpose of organization only. All Seghra classified robots lack the capacity to give orders.
*Somur - Somur is a rank that can be held by either a human or an intelligent robot in the [[Lorithos]] forces. A human Somur is usually a non-combat position, and is typically assigned to robot or vehicle maintenance. Somur do not have a rank emblem.
*Rehg Maht - A Rehg Maht is a human rank, and typically is responsible for subsystems in tanks, defensive positions, and similar jobs. A Rehg maht wears a black crescent moon.
*Maht - A Maht is a Rak Aree level supervisor, the second-in-command of the top tank, or the head of robotics maintenance in an infantry Rak Aree. A Maht wears two black crescent moons.
*Suraf - A Suraf is a Rak Sur level supervisor. A Suraf wears three black crescent moons.
*Ara Suraf - An Ara Suraf is a Sheren level supervisor. An Ara Suraf wears four black crescent moons.
*Breg Suraf - A Breg Suraf is a Sheren Ahk level supervisor. A Breg Suraf wears four black crescent moons and a silver sun.
*Zuura Suraf - A Zuura Suraf is a Brohgen level supervisor. A Zuura Suraf wears four black crescent moons and two silver suns.
*Ersa Suraf iv Getah - The Ersa Suraf iv Getah (usually just known as the Ersa Suraf) is the direct aide to the [[Hishai]]. There is only one Ersa Suraf in the [[Mozihr Getah Tashir Fahr‎|Mozihr Getah]], and his main duty is to act as the [[Hishai]]'s advisor in understanding the Wehrmon ranks. The Ersa Suraf wears four black crescent moons and three silver suns.

==Kihtan==
Kihtan officers are given formal orders from the [[Prekohr]] and the [[Hishai]], granting them their rank and privaledges. This carries a great deal of honor and responsibility. Any Kihtan is expected to fight, think, and lead.

*Urta So - An Urta So is in command of a Rak Aree. An Urta So wears a gold sun with rays.
*Urta De - An officer holding the rank of Urta De is in command of a Rak Sur. An Urta De wears a gold sun with rays and a silver moon.
*Krel Mag - A Krel Mag commands a Sheren. A Krel Mag wears a gold sun with rays and two silver moons.
*Jigor - A Jigor commands a Sheren Ahk. A Jigor wears a gold sun with three silver moons.
*Urta Kasoff - An Urta Kasoff is an assistant in commanding a Brohgen, which is too large for an individual command. An Urta Kasoff wears a gold sun with three silver moons and a black crescent moon.
*Kasoff - A Kasoff is in command of a Brohgen. A Kasoff wears a gold sun with three moons and two black crescent moons.
*Ortun - An Ortun commands a Qor Brin. An Ortun wears two gold suns.
*Urta Resun - An Urta Resun coordinates between Qor Brin and Qor Urts, and acts as a second-in-command for a Qor Urt. An Urta Resun wears two gold suns and a black moon.
*Resun - A Resun commands a Qor Urt, and is responsible for the defense of an entire planet within [[Rikaz o Fii Huern iv Lorithan]]. Resuns report directly to the Hishai. A Resun wears two gold suns and two black moons.
*Hishai - The [[Hishai]] is the supreme commander of all [[Lorithos]] forces. The [[Hishai]] wears three gold suns and the [[Lorithos]] emblem.

[[Category:Rikaz o Fii Huern iv Lorithan]]`
